/* Y Axis Tuition, shared script: language switch (EN/தமிழ்), enquiry form, gallery, menu, motion. */
const P="+91 78455 92859",WA="https://wa.me/917845592859",$=s=>document.querySelector(s);
const TA={"Home": "முகப்பு", "About Us": "எங்களைப் பற்றி", "Academic Programmes": "கல்வித் திட்டங்கள்", "Gallery": "படத்தொகுப்பு", "Contact Us": "தொடர்புக்கு", "Enquiry": "விசாரணை", "Every Child Has a Spark. Let Us Help Them Shine.": "ஒவ்வொரு குழந்தையிடமும் ஒரு திறமை உண்டு. அவர்கள் ஒளிர நாங்கள் உதவுவோம்.", "Every mind has potential. Every child has a dream. With the right guidance, patience, and encouragement, every learner deserves the opportunity to succeed.": "ஒவ்வொரு மனமும் திறன் கொண்டது. ஒவ்வொரு குழந்தைக்கும் ஒரு கனவு உண்டு. சரியான வழிகாட்டுதல், பொறுமை மற்றும் ஊக்கத்துடன், ஒவ்வொரு மாணவரும் வெற்றி பெற தகுதியானவர்.", "Has your child been struggling to understand lessons? Does your child find it difficult to concentrate, keep up with schoolwork, or perform well academically? Have you ever been told that your child is not progressing as expected?": "உங்கள் குழந்தை பாடங்களைப் புரிந்துகொள்ள சிரமப்படுகிறதா? கவனம் செலுத்துவது, பள்ளிப் படிப்பைத் தொடர்வது அல்லது கல்வியில் சிறப்பாகச் செயல்படுவது கடினமாக உள்ளதா? உங்கள் குழந்தை எதிர்பார்த்த அளவு முன்னேறவில்லை என்று உங்களிடம் சொல்லப்பட்டிருக்கிறதா?", "At Y Axis Tuition, we believe that no child is incapable of learning. Every child simply needs the right guidance, individual attention, and a supportive learning environment. We identify learning difficulties, strengthen academic foundations, build confidence, and guide students towards continuous improvement.": "Y Axis Tuition-இல், எந்தக் குழந்தையும் கற்க இயலாதவர் அல்ல என்று நாங்கள் நம்புகிறோம். ஒவ்வொரு குழந்தைக்கும் சரியான வழிகாட்டுதல், தனிப்பட்ட கவனம் மற்றும் ஆதரவான கற்றல் சூழல் மட்டுமே தேவை. கற்றல் சிரமங்களைக் கண்டறிந்து, கல்வி அடித்தளத்தை வலுப்படுத்தி, தன்னம்பிக்கையை வளர்த்து, தொடர்ந்த முன்னேற்றத்தை நோக்கி மாணவர்களை வழிநடத்துகிறோம்.", "<b>Your child's progress is our priority. Their growth is our commitment.</b>": "<b>உங்கள் குழந்தையின் முன்னேற்றமே எங்கள் முன்னுரிமை. அவர்களின் வளர்ச்சியே எங்கள் உறுதிப்பாடு.</b>", "Your child's progress is our priority. Their growth is our commitment.": "உங்கள் குழந்தையின் முன்னேற்றமே எங்கள் முன்னுரிமை. அவர்களின் வளர்ச்சியே எங்கள் உறுதிப்பாடு.", "Explore Our Programmes": "எங்கள் திட்டங்களைப் பாருங்கள்", "Enquire Now": "இப்போதே விசாரிக்கவும்", "Confidence": "தன்னம்பிக்கை", "Growth": "வளர்ச்சி", "Guidance": "வழிகாட்டுதல்", "A Place Where Every Child Matters.": "ஒவ்வொரு குழந்தையும் முக்கியமான இடம்.", "Not every student learns at the same pace. Some students understand concepts quickly, while others require additional time, patience, and individual attention.": "எல்லா மாணவர்களும் ஒரே வேகத்தில் கற்பதில்லை. சிலர் கருத்துகளை விரைவாகப் புரிந்துகொள்கிறார்கள்; மற்றவர்களுக்கு கூடுதல் நேரம், பொறுமை மற்றும் தனிப்பட்ட கவனம் தேவைப்படுகிறது.", "At Y Axis Tuition, we do not define a student's ability by their current academic performance. Instead, we focus on understanding their learning difficulties, identifying knowledge gaps, and providing the right support to help them improve.": "Y Axis Tuition-இல், ஒரு மாணவரின் தற்போதைய மதிப்பெண்களை வைத்து அவர்களின் திறனை நாங்கள் மதிப்பிடுவதில்லை. மாறாக, அவர்களின் கற்றல் சிரமங்களைப் புரிந்துகொண்டு, அறிவு இடைவெளிகளைக் கண்டறிந்து, முன்னேற சரியான ஆதரவை வழங்குகிறோம்.", "Our teaching approach is built around individual attention, experienced female educators, structured learning methods, and continuous academic monitoring. We believe that every student deserves to be understood, encouraged, and given the opportunity to achieve their full potential.": "எங்கள் கற்பித்தல் முறை தனிப்பட்ட கவனம், அனுபவமுள்ள ஆசிரியைகள், ஒழுங்கமைந்த கற்றல் முறைகள் மற்றும் தொடர்ந்த கல்விக் கண்காணிப்பை அடிப்படையாகக் கொண்டது. ஒவ்வொரு மாணவரும் புரிந்துகொள்ளப்பட வேண்டும், ஊக்குவிக்கப்பட வேண்டும், தங்கள் முழுத் திறனை அடையும் வாய்ப்பு பெற வேண்டும் என்று நாங்கள் நம்புகிறோம்.", "We don't label students by their weaknesses. We help them grow beyond them.": "மாணவர்களை அவர்களின் பலவீனங்களால் நாங்கள் அடையாளப்படுத்துவதில்லை. அவற்றைத் தாண்டி வளர அவர்களுக்கு உதவுகிறோம்.", "Learning Programmes for Every Stage of Education.": "கல்வியின் ஒவ்வொரு நிலைக்கும் ஏற்ற கற்றல் திட்டங்கள்.", "We offer structured academic support for students from Primary to Higher Secondary Education, with teaching methods designed to suit their academic levels and individual learning needs.": "தொடக்கக் கல்வி முதல் மேல்நிலைக் கல்வி வரையிலான மாணவர்களுக்கு, அவர்களின் கல்வி நிலை மற்றும் தனிப்பட்ட கற்றல் தேவைகளுக்கு ஏற்ற கற்பித்தல் முறைகளுடன் ஒழுங்கமைந்த கல்வி ஆதரவை வழங்குகிறோம்.", "Classes 1–5": "வகுப்புகள் 1–5", "Primary Education": "தொடக்கக் கல்வி", "Building strong academic foundations through reading, writing, basic mathematics, language development, and essential subject knowledge.": "வாசிப்பு, எழுத்து, அடிப்படைக் கணிதம், மொழி வளர்ச்சி மற்றும் அத்தியாவசியப் பாட அறிவு மூலம் வலுவான கல்வி அடித்தளத்தை உருவாக்குதல்.", "Classes 6–8": "வகுப்புகள் 6–8", "Middle School Education": "நடுநிலைக் கல்வி", "Strengthening conceptual understanding, developing independent learning habits, and improving knowledge across all major subjects.": "கருத்துப் புரிதலை வலுப்படுத்துதல், சுயமாகக் கற்கும் பழக்கங்களை வளர்த்தல் மற்றும் அனைத்து முக்கியப் பாடங்களிலும் அறிவை மேம்படுத்துதல்.", "Classes 9–10": "வகுப்புகள் 9–10", "Secondary Education": "உயர்நிலைக் கல்வி", "Focused academic guidance, subject-wise learning support, regular practice, revision, and examination preparation.": "கவனம் செலுத்திய கல்வி வழிகாட்டுதல், பாடவாரியான கற்றல் ஆதரவு, தொடர் பயிற்சி, மறுபார்வை மற்றும் தேர்வுத் தயாரிப்பு.", "Classes 11–12": "வகுப்புகள் 11–12", "Higher Secondary Education": "மேல்நிலைக் கல்வி", "Specialised academic support exclusively for girl students, focusing on subject understanding, individual learning difficulties, conceptual clarity, and examination preparation.": "மாணவிகளுக்கு மட்டுமேயான சிறப்புக் கல்வி ஆதரவு. பாடப் புரிதல், தனிப்பட்ட கற்றல் சிரமங்கள், கருத்துத் தெளிவு மற்றும் தேர்வுத் தயாரிப்பில் கவனம் செலுத்தப்படுகிறது.", "Our Special Focus": "எங்கள் சிறப்புக் கவனம்", "Classes 10–12 are exclusively for girl students": "10–12 வகுப்புகள் மாணவிகளுக்கு மட்டுமே", "A comfortable, supportive, and girls-focused learning environment led by female teachers.": "ஆசிரியைகள் நடத்தும், வசதியான, ஆதரவான, மாணவிகளை மையமாகக் கொண்ட கற்றல் சூழல்.", "Girls only": "மாணவிகள் மட்டும்", "Female teachers": "ஆசிரியைகள்", "Comfortable &amp; safe": "வசதியானது &amp; பாதுகாப்பானது", "Extra Attention. Stronger Understanding. Better Performance.": "கூடுதல் கவனம். வலுவான புரிதல். சிறந்த செயல்திறன்.", "Some subjects require additional explanation, consistent practice, and individual guidance. Our special academic coaching sessions help students overcome subject-related difficulties and develop stronger academic foundations.": "சில பாடங்களுக்கு கூடுதல் விளக்கம், தொடர் பயிற்சி மற்றும் தனிப்பட்ட வழிகாட்டுதல் தேவைப்படுகிறது. எங்கள் சிறப்புக் கல்விப் பயிற்சி வகுப்புகள், பாடம் சார்ந்த சிரமங்களைக் கடக்கவும் வலுவான கல்வி அடித்தளத்தை உருவாக்கவும் மாணவர்களுக்கு உதவுகின்றன.", "Mathematics": "கணிதம்", "Developing numerical understanding, logical thinking, problem-solving abilities, and confidence in mathematics.": "எண் புரிதல், தர்க்க சிந்தனை, சிக்கல் தீர்க்கும் திறன் மற்றும் கணிதத்தில் தன்னம்பிக்கையை வளர்த்தல்.", "Science": "அறிவியல்", "Building scientific knowledge through clear explanations, conceptual learning, and practical understanding.": "தெளிவான விளக்கங்கள், கருத்து வழிக் கற்றல் மற்றும் நடைமுறைப் புரிதல் மூலம் அறிவியல் அறிவை வளர்த்தல்.", "Chemistry": "வேதியியல்", "Simplifying complex concepts, chemical equations, formulas, and subject-specific problem-solving.": "சிக்கலான கருத்துகள், வேதிச் சமன்பாடுகள், சூத்திரங்கள் மற்றும் பாடம் சார்ந்த கணக்குகளை எளிமைப்படுத்துதல்.", "All Major Subjects, Classes 1–9": "அனைத்து முக்கியப் பாடங்களும், வகுப்புகள் 1–9", "Comprehensive academic support across school subjects, helping students understand lessons, complete their learning requirements, and improve their performance.": "அனைத்துப் பள்ளிப் பாடங்களிலும் முழுமையான கல்வி ஆதரவு. பாடங்களைப் புரிந்துகொள்ளவும், கற்றல் தேவைகளை நிறைவு செய்யவும், செயல்திறனை மேம்படுத்தவும் மாணவர்களுக்கு உதவுகிறோம்.", "Weekend &amp; Holiday Special Classes": "வார இறுதி &amp; விடுமுறை சிறப்பு வகுப்புகள்", "We provide additional coaching sessions on Sundays, weekends, and school holidays for students who require extra academic support. These focus on:": "கூடுதல் கல்வி ஆதரவு தேவைப்படும் மாணவர்களுக்காக ஞாயிற்றுக்கிழமைகள், வார இறுதிகள் மற்றும் பள்ளி விடுமுறை நாட்களில் கூடுதல் பயிற்சி வகுப்புகளை நடத்துகிறோம். இவை கவனம் செலுத்துபவை:", "Students who are academically struggling": "கல்வியில் சிரமப்படும் மாணவர்கள்", "Difficult and challenging topics": "கடினமான மற்றும் சவாலான தலைப்புகள்", "Subject-specific learning difficulties": "பாடம் சார்ந்த கற்றல் சிரமங்கள்", "Additional practice and revision": "கூடுதல் பயிற்சி மற்றும் மறுபார்வை", "Examination preparation": "தேர்வுத் தயாரிப்பு", "Strengthening weak academic foundations": "பலவீனமான கல்வி அடித்தளத்தை வலுப்படுத்துதல்", "Sessions are planned according to the student's academic requirements and specific subject needs.": "ஒவ்வொரு மாணவரின் கல்வித் தேவைகள் மற்றும் குறிப்பிட்ட பாடத் தேவைகளுக்கு ஏற்ப வகுப்புகள் திட்டமிடப்படுகின்றன.", "A Safe Space to Learn. A Confident Space to Grow.": "கற்க பாதுகாப்பான இடம். வளர நம்பிக்கையான இடம்.", "At Y Axis Tuition, we give special importance to creating a comfortable, respectful, and supportive learning environment for girl students. Our teaching team consists entirely of female teachers who focus on patience, encouragement, individual attention, and student development. For Classes 10–12, we provide an exclusively girls-only learning environment.": "Y Axis Tuition-இல், மாணவிகளுக்கு வசதியான, மரியாதையான மற்றும் ஆதரவான கற்றல் சூழலை உருவாக்குவதற்கு நாங்கள் சிறப்பு முக்கியத்துவம் அளிக்கிறோம். எங்கள் ஆசிரியர் குழு முழுவதும் ஆசிரியைகளே; அவர்கள் பொறுமை, ஊக்கம், தனிப்பட்ட கவனம் மற்றும் மாணவர் வளர்ச்சியில் கவனம் செலுத்துகிறார்கள். 10–12 வகுப்புகளுக்கு மாணவிகளுக்கு மட்டுமேயான கற்றல் சூழலை வழங்குகிறோம்.", "We encourage every girl student to:": "ஒவ்வொரு மாணவியையும் நாங்கள் ஊக்குவிக்கிறோம்:", "Ask questions without hesitation": "தயக்கமின்றிக் கேள்விகள் கேட்க", "Express learning difficulties freely": "கற்றல் சிரமங்களைத் தயக்கமின்றிச் சொல்ல", "Participate confidently in classroom activities": "வகுப்புச் செயல்பாடுகளில் நம்பிக்கையுடன் பங்கேற்க", "Develop independent thinking": "சுயமாகச் சிந்திக்கும் திறனை வளர்க்க", "Improve academic performance": "கல்விச் செயல்திறனை மேம்படுத்த", "Build self-confidence and communication skills": "தன்னம்பிக்கை மற்றும் தொடர்புத் திறன்களை வளர்க்க", "Dear Parents,": "அன்புள்ள பெற்றோர்களே,", "Your daughter's education, comfort, and academic development matter to us. We strive to provide a learning environment where parents can feel confident about their daughters' educational journey.": "உங்கள் மகளின் கல்வி, வசதி மற்றும் கல்வி வளர்ச்சி எங்களுக்கு முக்கியம். பெற்றோர்கள் தங்கள் மகள்களின் கல்விப் பயணத்தைப் பற்றி நம்பிக்கை கொள்ளக்கூடிய கற்றல் சூழலை வழங்க நாங்கள் முயல்கிறோம்.", "Educating Girls. Empowering Futures.": "பெண் குழந்தைகளுக்குக் கல்வி. எதிர்காலத்திற்கு வலிமை.", "More Than Tuition. A Commitment to Your Child's Growth.": "வெறும் டியூஷன் அல்ல. உங்கள் குழந்தையின் வளர்ச்சிக்கான உறுதிப்பாடு.", "Special Attention for Every Learner": "ஒவ்வொரு மாணவருக்கும் சிறப்புக் கவனம்", "We identify individual learning difficulties and provide appropriate academic support rather than following the same teaching approach for every student.": "எல்லா மாணவர்களுக்கும் ஒரே கற்பித்தல் முறையைப் பின்பற்றுவதற்குப் பதிலாக, தனிப்பட்ட கற்றல் சிரமங்களைக் கண்டறிந்து உரிய கல்வி ஆதரவை வழங்குகிறோம்.", "Experienced Female Teachers": "அனுபவமுள்ள ஆசிரியைகள்", "Our dedicated female educators focus on student understanding, patient teaching, academic development, and continuous encouragement.": "எங்கள் அர்ப்பணிப்புள்ள ஆசிரியைகள் மாணவர் புரிதல், பொறுமையான கற்பித்தல், கல்வி வளர்ச்சி மற்றும் தொடர்ந்த ஊக்கத்தில் கவனம் செலுத்துகிறார்கள்.", "Individual Learning Support": "தனிப்பட்ட கற்றல் ஆதரவு", "Every student is different. We understand individual learning abilities, identify academic gaps, and provide guidance based on each student's needs.": "ஒவ்வொரு மாணவரும் வேறுபட்டவர். தனிப்பட்ட கற்றல் திறன்களைப் புரிந்துகொண்டு, கல்வி இடைவெளிகளைக் கண்டறிந்து, ஒவ்வொருவரின் தேவைக்கு ஏற்ப வழிகாட்டுகிறோம்.", "Weekly Academic Tracking": "வாராந்திரக் கல்விக் கண்காணிப்பு", "We regularly monitor each student's learning activities, academic performance, subject understanding, and areas requiring improvement.": "ஒவ்வொரு மாணவரின் கற்றல் செயல்பாடுகள், கல்விச் செயல்திறன், பாடப் புரிதல் மற்றும் மேம்பட வேண்டிய பகுதிகளை முறையாகக் கண்காணிக்கிறோம்.", "Monthly Academic Progress Reports": "மாதாந்திரக் கல்வி முன்னேற்ற அறிக்கைகள்", "Parents receive monthly updates about their child's academic development, performance, strengths, and areas that need additional attention.": "உங்கள் குழந்தையின் கல்வி வளர்ச்சி, செயல்திறன், பலங்கள் மற்றும் கூடுதல் கவனம் தேவைப்படும் பகுதிகள் குறித்த மாதாந்திரத் தகவல்களைப் பெற்றோர்கள் பெறுகிறார்கள்.", "Regular Parent–Teacher Meetings": "முறையான பெற்றோர்–ஆசிரியர் சந்திப்புகள்", "We conduct parent–teacher meetings once every two months to discuss student performance, learning challenges, improvement, and future academic plans.": "மாணவர் செயல்திறன், கற்றல் சவால்கள், முன்னேற்றம் மற்றும் எதிர்காலக் கல்வித் திட்டங்களை விவாதிக்க, இரண்டு மாதங்களுக்கு ஒருமுறை பெற்றோர்–ஆசிரியர் சந்திப்பு நடத்துகிறோம்.", "Individual Student Report Cards": "தனிப்பட்ட மாணவர் மதிப்பெண் அறிக்கை", "Every student receives an individual report card to monitor academic performance and track learning progress over time.": "கல்விச் செயல்திறனைக் கண்காணிக்கவும் காலப்போக்கில் கற்றல் முன்னேற்றத்தைப் பின்தொடரவும், ஒவ்வொரு மாணவருக்கும் தனிப்பட்ட அறிக்கை அட்டை வழங்கப்படுகிறது.", "Transparent Parent Communication": "வெளிப்படையான பெற்றோர் தொடர்பு", "We maintain clear and consistent communication without hiding important updates, so parents are always informed.": "முக்கியத் தகவல்களை மறைக்காமல், தெளிவான மற்றும் தொடர்ச்சியான தகவல் தொடர்பைப் பராமரிக்கிறோம்; இதனால் பெற்றோர்கள் எப்போதும் அறிந்திருப்பார்கள்.", "Student Attendance Notifications": "மாணவர் வருகைப் பதிவு அறிவிப்புகள்", "Through our dedicated app, parents receive a notification when their child arrives at the tuition centre (check-in) and when they leave after class (check-out). The app also lets you see your son's or daughter's attendance and academic progress in detail.": "எங்கள் பிரத்யேக செயலி (App) மூலம், உங்கள் குழந்தை பயிற்சி மையத்திற்கு வரும்போதும் (Check-in), வகுப்பு முடிந்து புறப்படும்போதும் (Check-out) பெற்றோர்கள் அறிவிப்பைப் பெறுகிறார்கள். உங்கள் மகன் அல்லது மகளின் வருகைப் பதிவையும் கல்வி முன்னேற்றத்தையும் செயலியில் விரிவாகப் பார்க்கலாம்.", "Special Coaching &amp; Additional Support": "சிறப்புப் பயிற்சி &amp; கூடுதல் ஆதரவு", "Additional coaching for students who need extra help in specific subjects, particularly Mathematics, Science, and Chemistry.": "குறிப்பிட்ட பாடங்களில், குறிப்பாக கணிதம், அறிவியல் மற்றும் வேதியியலில், கூடுதல் உதவி தேவைப்படும் மாணவர்களுக்கு கூடுதல் பயிற்சி.", "Your Child's Learning Journey. Always Within Your Reach.": "உங்கள் குழந்தையின் கற்றல் பயணம். எப்போதும் உங்கள் கண் முன்னால்.", "Communication with parents is an essential part of our educational approach. We keep parents informed about their child's attendance, academic progress, and important updates. Our dedicated app-based system helps us stay connected with parents through regular attendance and academic progress updates.": "பெற்றோருடனான தொடர்பு எங்கள் கல்வி அணுகுமுறையின் முக்கிய பகுதியாகும். உங்கள் குழந்தையின் வருகை, கல்வி முன்னேற்றம் மற்றும் முக்கிய அறிவிப்புகள் குறித்து பெற்றோர்களுக்குத் தெரியப்படுத்துகிறோம். எங்கள் பிரத்யேக செயலி அடிப்படையிலான அமைப்பு, தொடர்ச்சியான வருகை மற்றும் கல்வி முன்னேற்றத் தகவல்கள் மூலம் பெற்றோர்களுடன் இணைந்திருக்க உதவுகிறது.", "Attendance Notifications": "வருகைப் பதிவு அறிவிப்புகள்", "Daily check-in notification through our app when your child arrives at the centre": "உங்கள் குழந்தை மையத்திற்கு வரும்போது எங்கள் செயலி மூலம் தினசரி வருகை அறிவிப்பு", "Daily check-out notification through our app when your child leaves after class": "வகுப்பு முடிந்து உங்கள் குழந்தை புறப்படும்போது எங்கள் செயலி மூலம் தினசரி புறப்பாடு அறிவிப்பு", "Academic Progress Updates": "கல்வி முன்னேற்றத் தகவல்கள்", "Weekly academic tracking report in PDF format, available to parents through our app": "வாராந்திரக் கல்விக் கண்காணிப்பு அறிக்கை PDF வடிவில், எங்கள் செயலி மூலம் பெற்றோர்களுக்குக் கிடைக்கும்", "Monthly academic progress report shared with parents through our app during the first week of each month": "மாதாந்திரக் கல்வி முன்னேற்ற அறிக்கை, ஒவ்வொரு மாதத்தின் முதல் வாரத்தில் எங்கள் செயலி மூலம் பெற்றோர்களுடன் பகிரப்படும்", "Individual report cards": "தனிப்பட்ட மதிப்பெண் அறிக்கைகள்", "Parent–teacher meetings every two months": "இரண்டு மாதங்களுக்கு ஒருமுறை பெற்றோர்–ஆசிரியர் சந்திப்புகள்", "Important Announcements": "முக்கிய அறிவிப்புகள்", "Advance notice of planned holidays": "திட்டமிடப்பட்ட விடுமுறைகள் பற்றிய முன்னறிவிப்பு", "Updates on special coaching sessions": "சிறப்புப் பயிற்சி வகுப்புகள் பற்றிய தகவல்கள்", "Important academic announcements": "முக்கியக் கல்வி அறிவிப்புகள்", "Student activities and schedules": "மாணவர் செயல்பாடுகள் மற்றும் அட்டவணைகள்", "<b>Our commitment to parents:</b> No confusion. No unnecessary surprises. Just clear, consistent, and transparent communication, because parents deserve to know how their children are learning, progressing, and growing.": "<b>பெற்றோர்களுக்கான எங்கள் உறுதிப்பாடு:</b> குழப்பம் இல்லை. தேவையற்ற அதிர்ச்சிகள் இல்லை. தெளிவான, தொடர்ச்சியான, வெளிப்படையான தகவல் தொடர்பு மட்டுமே, ஏனெனில் தங்கள் குழந்தைகள் எவ்வாறு கற்கிறார்கள், முன்னேறுகிறார்கள், வளர்கிறார்கள் என்பதை அறிய பெற்றோர்களுக்கு உரிமை உண்டு.", "Our commitment to parents:": "பெற்றோர்களுக்கான எங்கள் உறுதிப்பாடு:", "Small Steps Today. Greater Achievements Tomorrow.": "இன்றைய சிறு அடிகள். நாளைய பெரிய சாதனைகள்.", "Our goal is not limited to improving academic marks. We want students to become confident, curious, independent, and capable learners.": "கல்வி மதிப்பெண்களை உயர்த்துவது மட்டுமே எங்கள் இலக்கு அல்ல. மாணவர்கள் தன்னம்பிக்கை, ஆர்வம், சுதந்திரம் மற்றும் திறன் கொண்ட கற்பவர்களாக உருவாக வேண்டும் என்று விரும்புகிறோம்.", "Better Learning Environment": "சிறந்த கற்றல் சூழல்", "A calm, respectful space where questions are welcome.": "கேள்விகளை வரவேற்கும் அமைதியான, மரியாதையான இடம்.", "Improved Creativity": "மேம்பட்ட படைப்பாற்றல்", "Room to think differently and express ideas.": "வித்தியாசமாகச் சிந்திக்கவும் கருத்துகளை வெளிப்படுத்தவும் இடம்.", "Stronger Observation Skills": "வலுவான கவனிப்புத் திறன்", "Learning to notice details and connect concepts.": "விவரங்களைக் கவனித்து கருத்துகளை இணைக்கக் கற்றல்.", "Better Concentration": "சிறந்த கவனம்", "Structured sessions that build focus step by step.": "படிப்படியாகக் கவனத்தை வளர்க்கும் ஒழுங்கமைந்த வகுப்புகள்.", "Higher Self-Confidence": "அதிகத் தன்னம்பிக்கை", "Encouragement that helps students trust their abilities.": "மாணவர்கள் தங்கள் திறன்களை நம்ப உதவும் ஊக்கம்.", "Improved Academic Performance": "மேம்பட்ட கல்விச் செயல்திறன்", "Steady improvement through practice and review.": "பயிற்சி மற்றும் மறுபார்வை மூலம் நிலையான முன்னேற்றம்.", "Independent Thinking": "சுயமாகச் சிந்தித்தல்", "Learning to reason and solve problems alone.": "தாமாகவே யோசித்துச் சிக்கல்களைத் தீர்க்கக் கற்றல்.", "Better Communication Skills": "சிறந்த தொடர்புத் திறன்", "Confidence to speak, explain and ask.": "பேசவும், விளக்கவும், கேட்கவும் தன்னம்பிக்கை.", "Improved Study Habits": "மேம்பட்ட படிப்புப் பழக்கங்கள்", "Routines for revision, practice and organisation.": "மறுபார்வை, பயிற்சி மற்றும் ஒழுங்குக்கான வழக்கங்கள்.", "Future Educational Opportunities": "எதிர்காலக் கல்வி வாய்ப்புகள்", "Strong foundations that keep doors open.": "வாய்ப்புகளின் கதவுகளைத் திறந்து வைக்கும் வலுவான அடித்தளம்.", "Your Trust. Our Responsibility. Your Child's Future.": "உங்கள் நம்பிக்கை. எங்கள் பொறுப்பு. உங்கள் குழந்தையின் எதிர்காலம்.", "We understand that choosing the right tuition centre is an important decision for every parent. When you entrust your child to Y Axis Tuition, we take that responsibility seriously. We are committed to:": "ஒரு பயிற்சி மையத்தைத் தேர்ந்தெடுப்பது ஒவ்வொரு பெற்றோருக்கும் முக்கியமான முடிவு என்பதை நாங்கள் அறிவோம். உங்கள் குழந்தையை Y Axis Tuition-இடம் ஒப்படைக்கும்போது, அந்தப் பொறுப்பை நாங்கள் மிகத் தீவிரமாக எடுத்துக்கொள்கிறோம். நாங்கள் உறுதியளிப்பது:", "Understanding your child's academic difficulties": "உங்கள் குழந்தையின் கல்விச் சிரமங்களைப் புரிந்துகொள்வது", "Providing patient and structured teaching": "பொறுமையான மற்றும் ஒழுங்கமைந்த கற்பித்தலை வழங்குவது", "Giving individual attention wherever needed": "தேவையான இடங்களில் தனிப்பட்ட கவனம் செலுத்துவது", "Monitoring academic progress regularly": "கல்வி முன்னேற்றத்தை முறையாகக் கண்காணிப்பது", "Keeping parents informed through consistent updates": "தொடர்ந்த தகவல்கள் மூலம் பெற்றோர்களுக்குத் தெரியப்படுத்துவது", "Identifying areas that require additional attention": "கூடுதல் கவனம் தேவைப்படும் பகுதிகளைக் கண்டறிவது", "Encouraging confidence and positive learning habits": "தன்னம்பிக்கையையும் நல்ல கற்றல் பழக்கங்களையும் ஊக்குவிப்பது", "Supporting every child's journey towards academic improvement": "ஒவ்வொரு குழந்தையின் கல்வி முன்னேற்றப் பயணத்திற்கும் துணை நிற்பது", "Meaningful academic progress takes time, patience, and consistent effort. We cannot promise overnight results, but we are committed to sincere guidance, dedicated teaching, and continuous academic support.": "அர்த்தமுள்ள கல்வி முன்னேற்றத்திற்கு நேரம், பொறுமை மற்றும் தொடர் முயற்சி தேவை. ஒரே இரவில் முடிவுகளைத் தருவதாக எங்களால் வாக்குறுதி அளிக்க முடியாது; ஆனால் உண்மையான வழிகாட்டுதல், அர்ப்பணிப்புடன் கூடிய கற்பித்தல் மற்றும் தொடர்ந்த கல்வி ஆதரவை வழங்க உறுதிபூண்டுள்ளோம்.", "The Right Place. The Right Guidance. A Brighter Future.": "சரியான இடம். சரியான வழிகாட்டுதல். ஒளிமயமான எதிர்காலம்.", "Perhaps you have been searching for the right place. Perhaps your child simply needs someone who understands their learning difficulties and believes in their potential.": "ஒருவேளை நீங்கள் சரியான இடத்தைத் தேடிக்கொண்டிருக்கலாம். ஒருவேளை உங்கள் குழந்தைக்கு, அவர்களின் கற்றல் சிரமங்களைப் புரிந்துகொண்டு அவர்களின் திறனை நம்பும் ஒருவர் தேவைப்படலாம்.", "<b>Your search ends here. Welcome to Y Axis Tuition.</b>": "<b>உங்கள் தேடல் இங்கே முடிகிறது. Y Axis Tuition-க்கு வரவேற்கிறோம்.</b>", "Your search ends here. Welcome to Y Axis Tuition.": "உங்கள் தேடல் இங்கே முடிகிறது. Y Axis Tuition-க்கு வரவேற்கிறோம்.", "Give your child the opportunity to learn with confidence, grow with guidance, and move towards a brighter academic future. Every great journey begins with a single step. Let that step begin with us.": "உங்கள் குழந்தை நம்பிக்கையுடன் கற்கவும், வழிகாட்டுதலுடன் வளரவும், ஒளிமயமான கல்வி எதிர்காலத்தை நோக்கிச் செல்லவும் வாய்ப்பளியுங்கள். ஒவ்வொரு சிறந்த பயணமும் ஒரு முதல் அடியில் தொடங்குகிறது. அந்த அடி எங்களுடன் தொடங்கட்டும்.", "Register Now": "இப்போதே பதிவு செய்யுங்கள்", "Give Your Child the Chance to Shine.": "உங்கள் குழந்தைக்கு ஒளிர ஒரு வாய்ப்பு கொடுங்கள்.", "Where Every Child Gets a Chance to Shine.": "ஒவ்வொரு குழந்தைக்கும் ஒளிர ஒரு வாய்ப்பு கிடைக்கும் இடம்.", "<em>Every Child Can Learn. Every Child Deserves a Chance.</em>": "<em>ஒவ்வொரு குழந்தையும் கற்க முடியும். ஒவ்வொரு குழந்தையும் ஒரு வாய்ப்புக்குத் தகுதியானவர்.</em>", "Every Child Can Learn. Every Child Deserves a Chance.": "ஒவ்வொரு குழந்தையும் கற்க முடியும். ஒவ்வொரு குழந்தையும் ஒரு வாய்ப்புக்குத் தகுதியானவர்.", "Quick Links": "விரைவு இணைப்புகள்", "Contact": "தொடர்புக்கு", "Y Axis Tuition Centre<br>Alagar Kovil Road,<br>Near BSNL Office,<br>Above RJ Mini Super Market,<br>Melur 625106,<br>Madurai, Tamil Nadu, India.": "Y Axis Tuition Centre<br>அழகர் கோவில் சாலை,<br>BSNL அலுவலகம் அருகில்,<br>RJ Mini Super Market மேலே,<br>மேலூர் 625106,<br>மதுரை, தமிழ்நாடு, இந்தியா.", "Phone:": "தொலைபேசி:", "Website:": "இணையதளம்:", "<b>Working Hours</b><br>Monday – Saturday: 4:30 PM – 7:30 PM": "<b>வேலை நேரம்</b><br>திங்கள் – சனி: மாலை 4:30 – 7:30", "Working Hours": "வேலை நேரம்", "© <span id=\"yr\">2026</span> Y Axis Tuition. All rights reserved.": "© <span id=\"yr\">2026</span> Y Axis Tuition. அனைத்து உரிமைகளும் பாதுகாக்கப்பட்டவை.", "Illustrative placeholder. Real photographs of our centre will appear here once uploaded.": "இது ஒரு விளக்கப் படம் மட்டுமே. எங்கள் மையத்தின் உண்மையான புகைப்படங்கள் பதிவேற்றப்பட்டதும் இங்கே தோன்றும்.", "Close": "மூடு", "About Y Axis Tuition": "Y Axis Tuition பற்றி", "Patience, individual attention and equal opportunity for every learner.": "ஒவ்வொரு கற்பவருக்கும் பொறுமை, தனிப்பட்ட கவனம் மற்றும் சம வாய்ப்பு.", "Our Story": "எங்கள் கதை", "Y Axis Tuition began with a simple idea: every child deserves the opportunity to receive quality academic support. Our journey started with home tutoring, where we spent two years working closely with students and understanding their individual academic needs.": "Y Axis Tuition ஒரு எளிய எண்ணத்துடன் தொடங்கியது: ஒவ்வொரு குழந்தையும் தரமான கல்வி ஆதரவைப் பெறத் தகுதியானவர். எங்கள் பயணம் வீட்டுப் பயிற்சியுடன் தொடங்கியது; இரண்டு ஆண்டுகள் மாணவர்களுடன் நெருக்கமாகப் பணியாற்றி, அவர்களின் தனிப்பட்ட கல்வித் தேவைகளைப் புரிந்துகொண்டோம்.", "We recognised that some students were not receiving the additional attention and guidance they needed to overcome their learning difficulties. We wanted to create a place where students would not be judged by their marks, but would receive the patience, encouragement, and structured teaching required to improve. This vision inspired us to establish Y Axis Tuition at a dedicated location in Melur.": "சில மாணவர்கள் தங்கள் கற்றல் சிரமங்களைக் கடக்கத் தேவையான கூடுதல் கவனத்தையும் வழிகாட்டுதலையும் பெறவில்லை என்பதை நாங்கள் உணர்ந்தோம். மாணவர்கள் மதிப்பெண்களால் மதிப்பிடப்படாமல், முன்னேறத் தேவையான பொறுமை, ஊக்கம் மற்றும் ஒழுங்கமைந்த கற்பித்தலைப் பெறும் இடத்தை உருவாக்க விரும்பினோம். இந்த எண்ணமே மேலூரில் ஒரு தனி இடத்தில் Y Axis Tuition-ஐத் தொடங்க எங்களைத் தூண்டியது.", "Today, our focus is on strengthening academic foundations, improving learning abilities, supporting academically struggling students, and creating a comfortable learning environment with special emphasis on girl students.": "இன்று, கல்வி அடித்தளத்தை வலுப்படுத்துதல், கற்றல் திறன்களை மேம்படுத்துதல், கல்வியில் சிரமப்படும் மாணவர்களுக்கு ஆதரவளித்தல் மற்றும் மாணவிகளுக்குச் சிறப்பு முக்கியத்துவத்துடன் வசதியான கற்றல் சூழலை உருவாக்குதல் ஆகியவற்றில் எங்கள் கவனம் உள்ளது.", "Our journey began with individual students. Our vision is to make a meaningful difference in every student's educational journey.": "எங்கள் பயணம் தனிப்பட்ட மாணவர்களுடன் தொடங்கியது. ஒவ்வொரு மாணவரின் கல்விப் பயணத்திலும் அர்த்தமுள்ள மாற்றத்தை ஏற்படுத்துவதே எங்கள் நோக்கம்.", "Philosophy, Mission &amp; Vision": "தத்துவம், நோக்கம் &amp; தொலைநோக்கு", "Educational Philosophy": "கல்வித் தத்துவம்", "Every child can learn, every child can improve. We never label a student as weak; we look for the gap and help close it.": "ஒவ்வொரு குழந்தையும் கற்க முடியும்; ஒவ்வொரு குழந்தையும் முன்னேற முடியும். எந்த மாணவரையும் பலவீனமானவர் என்று நாங்கள் முத்திரை குத்துவதில்லை; இடைவெளியைக் கண்டறிந்து அதை நிரப்ப உதவுகிறோம்.", "Our Mission": "எங்கள் நோக்கம்", "To help academically struggling students improve their understanding, strengthen their foundations, and become confident learners. Our main focus is a comfortable learning environment for girl students: Classes 10–12 are exclusively for girls, and all our teachers are women.": "கல்வியில் சிரமப்படும் மாணவர்கள் தங்கள் புரிதலை மேம்படுத்தவும், அடித்தளத்தை வலுப்படுத்தவும், தன்னம்பிக்கை மிக்க கற்பவர்களாக ஆகவும் உதவுவது. மாணவிகளுக்கு வசதியான கற்றல் சூழலை வழங்குவதே எங்கள் முக்கிய கவனம்: 10–12 வகுப்புகள் மாணவிகளுக்கு மட்டுமே, எங்கள் ஆசிரியர்கள் அனைவரும் பெண்கள்.", "Our Vision": "எங்கள் தொலைநோக்கு", "A place where no child is left behind because of academic difficulties, and where girl students study in comfort and safety.": "கல்விச் சிரமங்களால் எந்தக் குழந்தையும் பின்தங்காத, மாணவிகள் வசதியாகவும் பாதுகாப்பாகவும் படிக்கும் இடம்.", "Teaching Approach": "கற்பித்தல் அணுகுமுறை", "Individual attention, structured lessons, experienced female teachers, and continuous academic monitoring.": "தனிப்பட்ட கவனம், ஒழுங்கமைந்த பாடங்கள், அனுபவமுள்ள ஆசிரியைகள் மற்றும் தொடர்ந்த கல்விக் கண்காணிப்பு.", "Commitment to Students &amp; Parents": "மாணவர்கள் &amp; பெற்றோர்களுக்கான உறுதிப்பாடு", "Patient teaching for students; clear, regular and transparent updates for parents.": "மாணவர்களுக்குப் பொறுமையான கற்பித்தல்; பெற்றோர்களுக்குத் தெளிவான, தொடர்ச்சியான, வெளிப்படையான தகவல்கள்.", "A Message from Our Founder": "எங்கள் நிறுவனரிடமிருந்து ஒரு செய்தி", "C. Manimegalai": "C. மணிமேகலை", "M.Sc. in Software Engineering<br>Founder of Y Axis Tuition Centre": "M.Sc. மென்பொருள் பொறியியல்<br>Y Axis Tuition Centre நிறுவனர்", "Patience, care and the right guidance can help every child grow with confidence.": "பொறுமை, அக்கறை மற்றும் சரியான வழிகாட்டுதல் ஒவ்வொரு குழந்தையும் நம்பிக்கையுடன் வளர உதவும்.", "My educational journey began with a strong interest in technology and professional development. I completed my engineering degree in 2013, followed by a career in the software industry.": "என் கல்விப் பயணம் தொழில்நுட்பம் மற்றும் தொழில்முறை வளர்ச்சியின் மீதான ஆழ்ந்த ஆர்வத்துடன் தொடங்கியது. 2013-ஆம் ஆண்டு என் பொறியியல் பட்டப்படிப்பை முடித்து, மென்பொருள் துறையில் பணியாற்றினேன்.", "I started my professional career as a Software Development Engineer in Chennai, where I worked for two years. I then moved to Singapore, where I continued working in the software industry for another two years. These experiences gave me valuable professional exposure, discipline, and an understanding of different working environments.": "என் தொழில்முறைப் பணியை சென்னையில் மென்பொருள் மேம்பாட்டுப் பொறியாளராகத் தொடங்கி, இரண்டு ஆண்டுகள் பணியாற்றினேன். பின்னர் சிங்கப்பூருக்குச் சென்று, மேலும் இரண்டு ஆண்டுகள் மென்பொருள் துறையில் தொடர்ந்தேன். இந்த அனுபவங்கள் எனக்கு மதிப்புமிக்க தொழில்முறை அனுபவத்தையும், ஒழுக்கத்தையும், பல்வேறு பணிச்சூழல்கள் பற்றிய புரிதலையும் கொடுத்தன.", "Due to family commitments, I eventually returned to India. After returning, I gained experience working in CBSE school environments, which further developed my interest in education and student learning. Over time, I realised that teaching was more than just a profession I was interested in. It was an opportunity to make a meaningful difference in children's lives.": "குடும்பக் கடமைகளால் நான் இறுதியில் இந்தியாவுக்குத் திரும்பினேன். திரும்பிய பிறகு CBSE பள்ளிச் சூழல்களில் பணியாற்றிய அனுபவம் பெற்றேன்; அது கல்வி மற்றும் மாணவர் கற்றலில் என் ஆர்வத்தை மேலும் வளர்த்தது. காலப்போக்கில், கற்பித்தல் நான் ஆர்வம் கொண்ட ஒரு தொழில் மட்டுமல்ல; குழந்தைகளின் வாழ்க்கையில் அர்த்தமுள்ள மாற்றத்தை ஏற்படுத்தும் வாய்ப்பு என்பதை உணர்ந்தேன்.", "For the past two years, I have been conducting home tuition, working closely with students and understanding their individual learning difficulties, academic challenges, and educational needs. Many students who struggle academically need more than ordinary classroom instruction. They need patience, individual attention, encouragement, and a teaching approach that suits their learning abilities. This realisation inspired me to establish Y Axis Tuition as a dedicated learning centre in Melur.": "கடந்த இரண்டு ஆண்டுகளாக வீட்டுப் பயிற்சி வகுப்புகள் நடத்தி, மாணவர்களுடன் நெருக்கமாகப் பணியாற்றி, அவர்களின் தனிப்பட்ட கற்றல் சிரமங்கள், கல்விச் சவால்கள் மற்றும் தேவைகளைப் புரிந்துகொண்டேன். கல்வியில் சிரமப்படும் பல மாணவர்களுக்குச் சாதாரண வகுப்பறைக் கற்பித்தலைவிட அதிகம் தேவை. அவர்களுக்குப் பொறுமை, தனிப்பட்ட கவனம், ஊக்கம் மற்றும் அவர்களின் கற்றல் திறனுக்கு ஏற்ற கற்பித்தல் முறை தேவை. இந்த உணர்வே மேலூரில் Y Axis Tuition-ஐ ஒரு தனிக் கற்றல் மையமாக நிறுவ என்னைத் தூண்டியது.", "My Vision Behind Y Axis Tuition": "Y Axis Tuition-க்குப் பின்னால் உள்ள என் தொலைநோக்கு", "My primary goal is simple: I want to help students who struggle academically improve their understanding, strengthen their foundations, and become confident learners. I strongly believe that no child should be labelled as a weak student or denied the opportunity to improve.": "என் முதன்மை இலக்கு எளிமையானது: கல்வியில் சிரமப்படும் மாணவர்கள் தங்கள் புரிதலை மேம்படுத்தவும், அடித்தளத்தை வலுப்படுத்தவும், தன்னம்பிக்கை மிக்க கற்பவர்களாக ஆகவும் உதவ விரும்புகிறேன். எந்தக் குழந்தையும் பலவீனமான மாணவர் என்று முத்திரை குத்தப்படக் கூடாது, முன்னேறும் வாய்ப்பு மறுக்கப்படக் கூடாது என்று நான் உறுதியாக நம்புகிறேன்.", "I also want to provide girl students with a comfortable, supportive, and safe learning environment where they can study confidently and express themselves freely. For me, Y Axis Tuition is not simply a business. It is a meaningful educational initiative built around patience, individual attention, equal opportunity, and student development. I want every parent who comes to Y Axis Tuition to feel confident that their child is receiving the guidance and attention they deserve.": "மாணவிகளுக்கு வசதியான, ஆதரவான மற்றும் பாதுகாப்பான கற்றல் சூழலை வழங்கவும் விரும்புகிறேன்; அங்கு அவர்கள் நம்பிக்கையுடன் படிக்கவும், சுதந்திரமாகத் தங்களை வெளிப்படுத்தவும் முடியும். என்னைப் பொறுத்தவரை, Y Axis Tuition வெறும் வணிகம் அல்ல. இது பொறுமை, தனிப்பட்ட கவனம், சம வாய்ப்பு மற்றும் மாணவர் வளர்ச்சியை அடிப்படையாகக் கொண்ட அர்த்தமுள்ள கல்வி முயற்சி. Y Axis Tuition-க்கு வரும் ஒவ்வொரு பெற்றோரும், தங்கள் குழந்தை தகுதியான வழிகாட்டுதலையும் கவனத்தையும் பெறுகிறது என்று நம்பிக்கை கொள்ள வேண்டும் என்பதே என் விருப்பம்.", "Structured support from Primary to Higher Secondary, with Classes 10–12 exclusively for girl students.": "தொடக்கக் கல்வி முதல் மேல்நிலைக் கல்வி வரை ஒழுங்கமைந்த ஆதரவு; 10–12 வகுப்புகள் மாணவிகளுக்கு மட்டும்.", "Special Academic Coaching": "சிறப்புக் கல்விப் பயிற்சி", "Extra attention in the subjects that need it most.": "மிகவும் தேவைப்படும் பாடங்களில் கூடுதல் கவனம்.", "Numerical understanding, logical thinking and problem-solving.": "எண் புரிதல், தர்க்க சிந்தனை மற்றும் சிக்கல் தீர்க்கும் திறன்.", "Clear explanations and conceptual learning.": "தெளிவான விளக்கங்கள் மற்றும் கருத்து வழிக் கற்றல்.", "Concepts, equations, formulas and problem-solving.": "கருத்துகள், சமன்பாடுகள், சூத்திரங்கள் மற்றும் கணக்குகளைத் தீர்த்தல்.", "Comprehensive support across school subjects.": "அனைத்துப் பள்ளிப் பாடங்களிலும் முழுமையான ஆதரவு.", "Extra coaching on Sundays, weekends, and school holidays for students who need additional support: difficult topics, practice, revision and exam preparation. Sessions are planned according to each student's needs.": "கூடுதல் ஆதரவு தேவைப்படும் மாணவர்களுக்கு ஞாயிறு, வார இறுதி மற்றும் பள்ளி விடுமுறை நாட்களில் கூடுதல் பயிற்சி: கடினமான தலைப்புகள், பயிற்சி, மறுபார்வை மற்றும் தேர்வுத் தயாரிப்பு. ஒவ்வொரு மாணவரின் தேவைக்கும் ஏற்ப வகுப்புகள் திட்டமிடப்படுகின்றன.", "Frequently Asked Questions": "அடிக்கடி கேட்கப்படும் கேள்விகள்", "Which classes do you teach?": "எந்த வகுப்புகளுக்குப் பாடம் நடத்துகிறீர்கள்?", "Classes 1 to 12. Classes 10–12 are exclusively for girl students.": "1 முதல் 12 ஆம் வகுப்பு வரை. 10–12 வகுப்புகள் மாணவிகளுக்கு மட்டுமே.", "Who teaches the students?": "மாணவர்களுக்கு யார் பாடம் நடத்துகிறார்கள்?", "Our teaching team consists entirely of female teachers.": "எங்கள் ஆசிரியர் குழு முழுவதும் ஆசிரியைகளே.", "Do you guarantee results?": "முடிவுகளுக்கு உத்தரவாதம் தருகிறீர்களா?", "Progress takes time and consistent effort. We promise sincere guidance, dedicated teaching and continuous support.": "முன்னேற்றத்திற்கு நேரமும் தொடர் முயற்சியும் தேவை. உண்மையான வழிகாட்டுதல், அர்ப்பணிப்புடன் கூடிய கற்பித்தல் மற்றும் தொடர்ந்த ஆதரவை நாங்கள் உறுதியளிக்கிறோம்.", "When are classes held?": "வகுப்புகள் எப்போது நடைபெறும்?", "Monday – Saturday, 4:30 PM – 7:30 PM.": "திங்கள் – சனி, மாலை 4:30 – 7:30.", "Moments from our learning environment.": "எங்கள் கற்றல் சூழலின் தருணங்கள்.", "All": "அனைத்தும்", "Classroom Environment": "வகுப்பறைச் சூழல்", "Teaching Activities": "கற்பித்தல் செயல்பாடுகள்", "Student Learning": "மாணவர் கற்றல்", "Academic Activities": "கல்விச் செயல்பாடுகள்", "Special Coaching Sessions": "சிறப்புப் பயிற்சி வகுப்புகள்", "Educational Events": "கல்வி நிகழ்வுகள்", "Photo 1, coming soon": "புகைப்படம் 1, விரைவில்", "Photo 2, coming soon": "புகைப்படம் 2, விரைவில்", "These tiles are placeholders. Genuine photographs of our classrooms and activities will be added here; we do not present generated images as our actual students.": "இவை தற்காலிகப் படங்கள் மட்டுமே. எங்கள் வகுப்பறைகள் மற்றும் செயல்பாடுகளின் உண்மையான புகைப்படங்கள் இங்கே சேர்க்கப்படும்; உருவாக்கப்பட்ட படங்களை எங்கள் உண்மையான மாணவர்கள் என்று நாங்கள் காட்டுவதில்லை.", "We Are Here to Help Your Child Grow.": "உங்கள் குழந்தை வளர உதவ நாங்கள் இங்கே இருக்கிறோம்.", "Have questions about our academic programmes, special coaching sessions, or admissions? We would be happy to hear from you.": "எங்கள் கல்வித் திட்டங்கள், சிறப்புப் பயிற்சி வகுப்புகள் அல்லது சேர்க்கை குறித்து கேள்விகள் உள்ளதா? உங்களிடமிருந்து கேட்க நாங்கள் மகிழ்ச்சியடைவோம்.", "Y Axis Tuition Centre": "Y Axis Tuition Centre", "Alagar Kovil Road,<br>Near BSNL Office,<br>Above RJ Mini Super Market,<br>Melur 625106,<br>Madurai, Tamil Nadu, India.": "அழகர் கோவில் சாலை,<br>BSNL அலுவலகம் அருகில்,<br>RJ Mini Super Market மேலே,<br>மேலூர் 625106,<br>மதுரை, தமிழ்நாடு, இந்தியா.", "Phone &amp; WhatsApp": "தொலைபேசி &amp; WhatsApp", "Chat on WhatsApp": "WhatsApp-இல் தொடர்பு செய்ய", "<b>Monday – Saturday</b><br>4:30 PM to 7:30 PM": "<b>திங்கள் – சனி</b><br>மாலை 4:30 முதல் 7:30 வரை", "Monday – Saturday": "திங்கள் – சனி", "Directions": "வழிகாட்டுதல்", "Find us on Alagar Kovil Road in Melur, near the BSNL Office. Look for RJ Mini Supermarket; our centre is on the first floor above it.": "மேலூரில் அழகர் கோவில் சாலையில், BSNL அலுவலகம் அருகில் எங்களைக் காணலாம். RJ Mini Supermarket-ஐத் தேடுங்கள்; எங்கள் மையம் அதற்கு மேலே முதல் தளத்தில் உள்ளது.", "Open in Google Maps": "Google Maps-இல் திறக்க", "Send us a message": "எங்களுக்குச் செய்தி அனுப்புங்கள்", "Your Name *": "உங்கள் பெயர் *", "Contact Number *": "தொடர்பு எண் *", "Additional Message": "கூடுதல் செய்தி", "Submit WhatsApp Enquiry": "WhatsApp விசாரணையை அனுப்பு", "Admission Enquiry": "சேர்க்கை விசாரணை", "Tell us about your child and the support they need.": "உங்கள் குழந்தையைப் பற்றியும் அவர்களுக்குத் தேவையான ஆதரவைப் பற்றியும் எங்களுக்குச் சொல்லுங்கள்.", "Parent / Guardian Name *": "பெற்றோர் / பாதுகாவலர் பெயர் *", "Student Name *": "மாணவர் பெயர் *", "Student Gender *": "மாணவர் பாலினம் *", "Current Standard *": "தற்போதைய வகுப்பு *", "School Name *": "பள்ளியின் பெயர் *", "Board *": "பாடத்திட்டம் (Board) *", "Subjects Requiring Support *": "ஆதரவு தேவைப்படும் பாடங்கள் *", "OPT:Select": "தேர்ந்தெடுக்கவும்", "OPT:Girl": "பெண்", "OPT:Boy": "ஆண்", "OPT:CBSE": "CBSE", "OPT:State Board": "மாநிலப் பாடத்திட்டம்", "OPT:Other": "மற்றவை", "OPT:Class 1": "வகுப்பு 1", "OPT:Class 2": "வகுப்பு 2", "OPT:Class 3": "வகுப்பு 3", "OPT:Class 4": "வகுப்பு 4", "OPT:Class 5": "வகுப்பு 5", "OPT:Class 6": "வகுப்பு 6", "OPT:Class 7": "வகுப்பு 7", "OPT:Class 8": "வகுப்பு 8", "OPT:Class 9": "வகுப்பு 9", "OPT:Class 10": "வகுப்பு 10", "OPT:Class 11": "வகுப்பு 11", "OPT:Class 12": "வகுப்பு 12", "Submit Enquiry":"விசாரணையை அனுப்பு","Sending…":"அனுப்புகிறது…","Thank you! Your enquiry has been submitted. We will contact you shortly.":"நன்றி! உங்கள் விசாரணை சமர்ப்பிக்கப்பட்டது. விரைவில் உங்களைத் தொடர்பு கொள்வோம்.","Sorry, we could not send your enquiry right now. Please use the WhatsApp button or call +91 78455 92859.":"மன்னிக்கவும், உங்கள் விசாரணையை இப்போது அனுப்ப முடியவில்லை. WhatsApp பட்டனைப் பயன்படுத்தவும் அல்லது +91 78455 92859 எண்ணை அழைக்கவும்.","Thank you!":"நன்றி!","Your enquiry has been received. We will contact you soon. You can also call or WhatsApp us on +91 78455 92859.":"உங்கள் விசாரணை பெறப்பட்டது. விரைவில் உங்களைத் தொடர்பு கொள்வோம். நீங்கள் +91 78455 92859 எண்ணை அழைக்கலாம் அல்லது WhatsApp செய்யலாம்.","Back to Home":"முகப்புக்குத் திரும்ப","Page not found":"பக்கம் கிடைக்கவில்லை","Sorry, we couldn't find the page you were looking for.":"மன்னிக்கவும், நீங்கள் தேடிய பக்கம் கிடைக்கவில்லை.","Go to Home":"முகப்புக்குச் செல்க","Open WhatsApp":"WhatsApp-ஐத் திறக்க","This field is required.": "இந்தப் புலம் அவசியம்.", "Enter a valid 10-digit Indian mobile number.": "சரியான 10 இலக்க மொபைல் எண்ணை உள்ளிடவும்.", "Opening WhatsApp with your details. Please press <b>Send</b> in WhatsApp to complete your enquiry.": "உங்கள் விவரங்களுடன் WhatsApp திறக்கப்படுகிறது. விசாரணையை முடிக்க WhatsApp-இல் <b>Send</b> அழுத்தவும்.", "Y Axis Tuition, Melur | Where Every Child Gets a Chance to Shine": "Y Axis Tuition, மேலூர் | ஒவ்வொரு குழந்தைக்கும் ஒளிர ஒரு வாய்ப்பு", "About Us | Y Axis Tuition, Melur": "எங்களைப் பற்றி | Y Axis Tuition, மேலூர்", "Academic Programmes | Y Axis Tuition, Melur": "கல்வித் திட்டங்கள் | Y Axis Tuition, மேலூர்", "Gallery | Y Axis Tuition, Melur": "படத்தொகுப்பு | Y Axis Tuition, மேலூர்", "Contact Us | Y Axis Tuition, Melur": "தொடர்புக்கு | Y Axis Tuition, மேலூர்", "Admission Enquiry | Y Axis Tuition, Melur": "சேர்க்கை விசாரணை | Y Axis Tuition, மேலூர்"};
let LANG="en";try{LANG=localStorage.getItem("yx_lang")=="ta"?"ta":"en"}catch(e){}
const tx=s=>LANG=="ta"&&TA[s]||s;
function tr(){document.documentElement.lang=LANG;
const lf=e=>e.tagName=="A"&&e.classList.contains("btn")||[...e.childNodes].every(n=>n.nodeType==3||(n.nodeType==1&&/^(B|STRONG|EM|BR|SPAN)$/.test(n.tagName)&&!n.querySelector("svg")));
[...document.querySelectorAll("header *, main *, footer *, .fab, #lb *")].filter(e=>!e.closest("svg")&&!e.closest("#lg")&&e.id!="lt"&&!/^(SCRIPT|STYLE|OPTION|SVG)$/i.test(e.tagName)&&lf(e)).forEach(e=>{if(!e.isConnected)return;
if(e.dataset.en==null){const h=e.innerHTML.replace(/\s+/g," ").trim();if(!h)return;e.dataset.en=h}
const k=e.dataset.en;if(!TA[k])return;const v=LANG=="ta"?TA[k]:k;if(e.innerHTML!==v)e.innerHTML=v});
document.querySelectorAll("option").forEach(o=>{if(o.dataset.en==null)o.dataset.en=o.textContent;const k="OPT:"+o.dataset.en;o.textContent=LANG=="ta"&&TA[k]||o.dataset.en});
const y=$("#yr");if(y)y.textContent=new Date().getFullYear();
document.querySelectorAll("#lg span").forEach((x,i)=>x.classList.toggle("on",(i==1)==(LANG=="ta")));
const lg=$("#lg");lg.setAttribute("aria-label",LANG=="ta"?"Switch to English":"தமிழுக்கு மாற்று");
if(window.cur&&titles[window.cur])document.title=tx(titles[window.cur])}
$("#lg").onclick=()=>{LANG=LANG=="ta"?"en":"ta";try{localStorage.setItem("yx_lang",LANG)}catch(e){}tr()};
function setup(){const f=$("#fm");if(!f)return;const fs=[...f.querySelectorAll("[required]")];
const chk=()=>{let ok=1;fs.forEach(e=>{let m="";const v=e.value.trim();if(!v)m=tx("This field is required.");else if(e.id=="ph"&&!/^(\+?91)?[6-9]\d{9}$/.test(v.replace(/[\s-]/g,"")))m=tx("Enter a valid 10-digit Indian mobile number.");$("#"+e.id+"e").textContent=m;e.setAttribute("aria-invalid",!!m);if(m)ok=0});return ok};
const msg=()=>"Y Axis Tuition enquiry:\n"+[...f.querySelectorAll("input,select,textarea")].filter(e=>e.value).map(e=>{const l=e.previousElementSibling,v=e.tagName=="SELECT"&&e.selectedOptions[0]&&e.selectedOptions[0].dataset.en||e.value;return (l.dataset.en||l.textContent).replace(" *","")+": "+v}).join("\n");
const wa=()=>{if(!chk())return;const o=$("#ok");o.className="";o.style.display="block";o.innerHTML=tx("Opening WhatsApp with your details. Please press <b>Send</b> in WhatsApp to complete your enquiry.");const u=WA+"?text="+encodeURIComponent(msg());o.innerHTML+=`<br><a class="btn" href="${u}" target="_blank" rel="noopener" style="margin-top:12px;display:inline-block">${tx("Open WhatsApp")}</a>`;let w=null;try{w=open(u,"_blank")}catch(_){}if(!w){try{location.href=u}catch(_){}}};
const NM={pn:"name",sn:"student_name",sg:"student_gender",cs:"current_standard",sc:"school_name",bd:"board",sj:"subjects_needed",ph:"phone",ms:"message"};
const em=async()=>{if(!chk())return;if($("#bf")&&$("#bf").value)return;const o=$("#ok"),b=$("#em");const d={"form-name":"enquiry","bot-field":"",page:window.cur||"",language:LANG};
f.querySelectorAll("input,select,textarea").forEach(e=>{if(NM[e.id]&&e.value)d[NM[e.id]]=e.tagName=="SELECT"&&e.selectedOptions[0]&&e.selectedOptions[0].dataset.en||e.value});
b.disabled=true;const t=b.textContent;b.textContent=tx("Sending…");
try{const r=await fetch("/",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:new URLSearchParams(d).toString()});if(!r.ok)throw 0;o.className="";o.innerHTML=tx("Thank you! Your enquiry has been submitted. We will contact you shortly.");f.reset()}catch(_){o.className="bad";o.innerHTML=tx("Sorry, we could not send your enquiry right now. Please use the WhatsApp button or call +91 78455 92859.")}
o.style.display="block";b.disabled=false;b.textContent=t};
f.onsubmit=e=>{e.preventDefault();em()};$("#wa").onclick=wa}
const cats=["All","Classroom Environment","Teaching Activities","Student Learning","Academic Activities","Special Coaching Sessions","Educational Events"];
function gal(){const fl=$("#fl");if(!fl)return;let cur="All";const gn=$("#gn");if(gn&&GALLERY.length)gn.style.display="none";
const draw=()=>{fl.innerHTML=cats.map(c=>`<button class="${c==cur?"on":""}">${c}</button>`).join("");fl.querySelectorAll("button").forEach((b,i)=>b.onclick=()=>{cur=cats[i];draw()});
const esc=x=>String(x).replace(/&/g,"&amp;").replace(/"/g,"&quot;").replace(/</g,"&lt;");
$("#gg").innerHTML=cats.slice(1).filter(c=>cur=="All"||c==cur).flatMap(c=>{const ph=GALLERY.filter(g=>g.cat==c);return ph.length?ph.map(g=>`<button class="gt gp" data-t="${esc(c)}" data-src="${GDIR+esc(g.file)}" data-alt="${esc(g.alt||c)}"><img src="${GDIR+esc(g.file)}" alt="${esc(g.alt||c)}" loading="lazy" onerror="this.closest('.gt').remove()"><span class="cap">${esc(c)}</span></button>`):[1,2].map(n=>`<button class="gt" data-t="${c}"><b>${c}</b><small>Photo ${n}, coming soon</small></button>`)}).join("");
document.querySelectorAll(".gt").forEach(g=>g.onclick=()=>{const src=g.dataset.src,li=$("#li");$("#lt").textContent=src?g.dataset.alt:tx(g.dataset.t);li.hidden=!src;if(src){li.src=src;li.alt=g.dataset.alt}$("#lp").style.display=src?"none":"";$("#lb").firstElementChild.classList.toggle("wide",!!src);$("#lb").style.display="grid";$("#lc").focus()});tr()};draw()}
if($("#lb")){$("#lc").onclick=()=>$("#lb").style.display="none";$("#lb").onclick=e=>{if(e.target.id=="lb")$("#lb").style.display="none"};document.onkeydown=e=>{if(e.key=="Escape")$("#lb").style.display="none"};}
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add("in");io.unobserve(e.target)}}),{threshold:.1});
const titles={home:"Y Axis Tuition, Melur | Where Every Child Gets a Chance to Shine",about:"About Us | Y Axis Tuition, Melur",programmes:"Academic Programmes | Y Axis Tuition, Melur",gallery:"Gallery | Y Axis Tuition, Melur",contact:"Contact Us | Y Axis Tuition, Melur",enquiry:"Admission Enquiry | Y Axis Tuition, Melur"};

