addEventListener("load",()=>setTimeout(()=>{const l=$("#ld");if(!l)return;l.style.opacity=0;setTimeout(()=>l.remove(),600)},350));

/* ---- smooth motion, scroll effects, draggable WhatsApp button ---- */
(()=>{const de=document.documentElement,rm=matchMedia("(prefers-reduced-motion:reduce)").matches,fine=matchMedia("(hover:hover) and (pointer:fine)").matches;
const sp=$("#sp"),hd=document.querySelector("header");
const fx=()=>{const y=scrollY,m=de.scrollHeight-innerHeight;sp.style.transform="scaleX("+(m>0?Math.min(1,y/m):0)+")";hd.classList.toggle("sc",y>8);
if(!rm){const hv=document.querySelector(".hv");if(hv&&y<900)hv.style.translate="0 "+(y*.07).toFixed(1)+"px"}};
let tk=0;addEventListener("scroll",()=>{if(!tk)tk=requestAnimationFrame(()=>{tk=0;fx()})},{passive:true});addEventListener("resize",fx);fx();
if(fine&&!rm){de.style.scrollBehavior="auto";let cur=scrollY,tar=scrollY,raf=0;
const step=()=>{cur+=(tar-cur)*.13;if(Math.abs(tar-cur)<.5){cur=tar;scrollTo(0,cur);raf=0;return}scrollTo(0,cur);raf=requestAnimationFrame(step)};
addEventListener("scroll",()=>{if(!raf){cur=tar=scrollY}},{passive:true});
addEventListener("wheel",e=>{if(e.ctrlKey||e.metaKey||e.defaultPrevented)return;if(Math.abs(e.deltaX)>Math.abs(e.deltaY))return;if(e.target.closest&&e.target.closest("textarea,select,#lb"))return;
const dy=e.deltaY*(e.deltaMode==1?34:e.deltaMode==2?innerHeight:1);e.preventDefault();if(!raf){cur=scrollY;tar=scrollY}
tar=Math.max(0,Math.min(de.scrollHeight-innerHeight,tar+dy));if(!raf)raf=requestAnimationFrame(step)},{passive:false})}
{de.classList.add("sl");const upd=()=>{const vh=innerHeight;document.querySelectorAll(".rv,.gt").forEach(e=>{if(e.classList.contains("fdl"))return;
if(e.dataset.i==null){const p=e.parentNode;e.dataset.i=p&&p.classList.contains("grid")?[...p.children].indexOf(e)%4:0}
const t0=+e.dataset.ty||0,top=e.getBoundingClientRect().top-t0;let p=(vh*.95-top-e.dataset.i*34)/(vh*.5);p=p<0?0:p>1?1:p;p=1-Math.pow(1-p,3);
const D=rm?36:(innerWidth<700?95:125),ty=(1-p)*D,tx_=(e.dataset.i%2?1:-1)*(1-p)*(rm?0:(innerWidth<700?26:46));e.dataset.ty=ty;e.style.opacity=p;e.style.transform=p>=1?"none":"translate3d("+tx_.toFixed(1)+"px,"+ty.toFixed(1)+"px,0) scale("+(.93+.07*p).toFixed(3)+")"})};
let q=0;const kick=()=>{if(!q)q=requestAnimationFrame(()=>{q=0;upd()})};addEventListener("scroll",kick,{passive:true});addEventListener("resize",kick);window.slu=kick;kick()}
const f=$(".fab");let sx,sy,ox,oy,mv=false,dr=false;
const place=(x,y)=>{const w=f.offsetWidth,h=f.offsetHeight;x=Math.max(4,Math.min(innerWidth-w-4,x));y=Math.max(4,Math.min(innerHeight-h-4,y));f.style.left=x+"px";f.style.top=y+"px";f.style.right="auto";f.style.bottom="auto"};
try{const p=JSON.parse(localStorage.getItem("yx_fab")||"null");if(p&&p.x>=0)place(p.x*innerWidth,p.y*innerHeight)}catch(e){}
f.title="Drag to move";
f.addEventListener("pointerdown",e=>{if(e.button)return;dr=true;mv=false;sx=e.clientX;sy=e.clientY;const r=f.getBoundingClientRect();ox=r.left;oy=r.top;try{f.setPointerCapture(e.pointerId)}catch(_){}});
f.addEventListener("pointermove",e=>{if(!dr)return;const dx=e.clientX-sx,dy=e.clientY-sy;if(!mv&&Math.hypot(dx,dy)<7)return;mv=true;f.classList.add("drag");place(ox+dx,oy+dy)});
const end=()=>{if(!dr)return;dr=false;f.classList.remove("drag");if(mv){const r=f.getBoundingClientRect();try{localStorage.setItem("yx_fab",JSON.stringify({x:r.left/innerWidth,y:r.top/innerHeight}))}catch(_){}}};
f.addEventListener("pointerup",end);f.addEventListener("pointercancel",end);
f.addEventListener("click",e=>{if(mv){e.preventDefault();e.stopPropagation();mv=false}},true);
f.addEventListener("dragstart",e=>e.preventDefault());
addEventListener("resize",()=>{if(f.style.left){const r=f.getBoundingClientRect();place(r.left,r.top)}});
})();
